"""List the icon names the deck can use (and the ones still being generated by the icon builder).

    python icons.py                  # counts and every name, by family
    python icons.py fabric lake      # only names containing any of the terms
    python icons.py --missing        # names that are planned but not generated yet

Families
  lucide     generic outline icons, in six colors (amber, azure, ink, muted, success, white): add_icon(s, "name", ..., color=)
  microsoft  official product icons (Fabric, Azure ML, Foundry, Key Vault, ...), one color: add_icon(s, "name", ...)
  tiles      text tiles for products with no official icon (MLflow, Spark, Delta, Databricks, ...): add_icon(s, "name", ...)
"""
from __future__ import annotations

import re
import sys
from pathlib import Path

ICONS = Path(__file__).resolve().parent / "assets" / "icons"
SCRIPT = ICONS / "scripts" / "build_icons.mjs"
COLORS = ("amber", "azure", "ink", "muted", "success", "white")


def slug(text: str) -> str:
    return re.sub(r"[^a-z0-9]+", "-", text.lower()).strip("-")


def planned() -> dict[str, set[str]]:
    out = {"lucide": set(), "microsoft": set(), "tiles": set()}
    if not SCRIPT.exists():
        return out
    src = SCRIPT.read_text(encoding="utf-8")
    m = re.search(r"const LUCIDE_REQUESTS = \[(.*?)\];", src, re.S)
    if m:
        out["lucide"] = set(re.findall(r"'([a-z0-9\-]+)'", m.group(1)))
    m = re.search(r"const MICROSOFT_ITEMS = \[(.*?)\n\];", src, re.S)
    if m:
        out["microsoft"] = set(re.findall(r"^\s{4}name: '([a-z0-9\-]+)'", m.group(1), re.M))
    m = re.search(r"const TEXT_TILES = \[(.*?)\];", src, re.S)
    if m:
        out["tiles"] = {slug(t) for t in re.findall(r"'([^']+)'", m.group(1))}
    return out


def present() -> dict[str, set[str]]:
    out = {"lucide": set(), "microsoft": set(), "tiles": set()}
    for col in COLORS:
        d = ICONS / "png" / col
        if d.exists():
            out["lucide"] |= {p.stem for p in d.glob("*.png")}
    for fam, d in (("microsoft", ICONS / "microsoft" / "png"), ("tiles", ICONS / "tiles")):
        if d.exists():
            out[fam] |= {p.stem for p in d.glob("*.png")}
    if (ICONS / "microsoft").exists() and not out["microsoft"]:
        out["microsoft"] = {p.stem for p in (ICONS / "microsoft").glob("*.png")}
    return out


def main(args: list[str]) -> None:
    missing_only = "--missing" in args
    terms = [a.lower() for a in args if not a.startswith("--")]
    have, plan = present(), planned()
    for fam in ("lucide", "microsoft", "tiles"):
        names = sorted(have[fam] | plan[fam])
        if terms:
            names = [n for n in names if any(t in n for t in terms)]
        if missing_only:
            names = [n for n in names if n not in have[fam]]
        ready = len(have[fam])
        total = len(have[fam] | plan[fam])
        print(f"\n[{fam}]  {ready} ready of {total} planned" + ("   (ready names are marked +, not generated yet -)" if not missing_only else ""))
        if not missing_only:
            print("  " + "  ".join(("+" if n in have[fam] else "-") + n for n in names))
        else:
            print("  " + "  ".join(names))


if __name__ == "__main__":
    main(sys.argv[1:])
